vector<long long> memo(100, -1);
long long fib(int n){
    if (n <= 1) return n;                 // base
    long long &ans = memo[n];
    if (ans != -1) return ans;            // NOTEBOOK CHECK
    return ans = fib(n-1) + fib(n-2);     // compute ONCE, store
}

// dp[i] = ways to reach stair i (moves 1 or 2)
int climb(int n){
    vector<int> dp(n + 1);
    dp[0] = 1;
    for (int i = 1; i <= n; i++) {
        dp[i] = dp[i-1];
        if (i >= 2) dp[i] += dp[i-2];
    }
    return dp[n];
}
